const outDir = path.join(__dirname, '..', 'frontend', 'config', 'guide-content', 'it');
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

const outPath = path.join(outDir, 'word-search-books-kdp.ts');
fs.writeFileSync(outPath, content, 'utf8');
console.log('Written:', outPath);

// Verification
const written = fs.readFileSync(outPath, 'utf8');

// Check for \uXXXX escape sequences (literal strings, not unicode chars)
const escapeMatches = written.match(/\\u[0-9a-fA-F]{4}/g);
if (escapeMatches) {
  console.error('ERROR: Found \\uXXXX escapes:', escapeMatches.slice(0, 10));
} else {
  console.log('OK: No \\uXXXX escapes found');
}

// Check titleTag length
const titleMatch = written.match(/titleTag:\s*'([^']+)'/);
if (titleMatch) {
  console.log(`titleTag: "${titleMatch[1]}" (${titleMatch[1].length} chars, max 60)`);
}

// Check metaDescription length
const metaMatch = written.match(/metaDescription:\s*'([^']+)'/);
if (metaMatch) {
  console.log(`metaDescription: "${metaMatch[1]}" (${metaMatch[1].length} chars, target 150-160)`);
}

// Check refund FAQ
if (written.includes('non offriamo rimborsi')) {
  console.log('OK: Refund policy FAQ present with "non offriamo rimborsi"');
} else {
  console.error('ERROR: Missing refund policy FAQ');
}

// Check sections
const sections = ['seo', 'hero', 'introduction', 'tutorial', 'platformTips', 'monetization', 'examples', 'faq', 'nextSteps', 'internalLinks', 'toolsRecommended', 'visuals', 'themeImages'];
sections.forEach(s => {
  if (written.includes(`${s}:`)) {
    console.log(`OK: Section "${s}" present`);
  } else {
    console.error(`ERROR: Section "${s}" missing`);
  }
});

// Check image paths
const requiredPaths = [
  '/samples/english/wordsearch/wordsearch portrait.webp',
  '/samples/english/wordsearch/custom word list.webp',
  '/samples/english/crossword/crossword_worksheet.webp',
  '/image-library/camping/backpack.webp',
  '/image-library/camping/bear.webp',
  '/image-library/camping/binoculars.webp',
  '/image-library/camping/boots.webp',
  '/image-library/camping/cabin.webp',
];
requiredPaths.forEach(p => {
  if (written.includes(p)) {
    console.log(`OK: Image path "${p}" present`);
  } else {
    console.error(`ERROR: Image path "${p}" missing`);
  }
});
